export const getDiagnosticQuestions = (stream: string): DiagnosticQuestion[] => {
  let questions: DiagnosticQuestion[] = [];

  switch (stream.toLowerCase()) {
    case 'neet':
      questions = [...BIO_NEET, ...C_NEET, ...P_NEET];
      break;
    case 'commerce':
    case 'cuet':
      questions = [...ACC_COM, ...ECO_COM, ...BS_COM];
      break;
    case 'foundation':
      questions = [...P_NEET.slice(0,4), ...C_NEET.slice(0,4), ...M_JEE.slice(0,6), ...BIO_NEET.slice(0,4)];
      break;
    case 'jee':
    default:
      questions = [...P_JEE, ...C_JEE, ...M_JEE];
      break;
  }

  // Sort by difficulty: easy → medium → hard (adaptive flow)
  const order = { easy: 0, medium: 1, hard: 2 };
  questions.sort((a, b) => order[a.difficulty] - order[b.difficulty]);

  return questions.slice(0, 30).map(q => ({ ...q, id: crypto.randomUUID() }));
};

