/**
 * ASAT Entrance Diagnostic — Class 10 level.
 * Used ONLY for the Foundation Assessment entrance test.
 * Class 11/12 getDiagnosticQuestions is used for the practice module.
 */
export const getASATDiagnosticQuestions = (stream: string): DiagnosticQuestion[] => {
  let subjectQs: DiagnosticQuestion[] = [];
  switch (stream.toLowerCase()) {
    case 'neet':
      subjectQs = [...ASAT_PHY, ...ASAT_CHEM, ...ASAT_BIO];
      break;
    case 'commerce':
    case 'cuet':
      subjectQs = [...ACC_COM, ...ECO_COM, ...BS_COM];
      break;
    default: // jee, foundation
      subjectQs = [...ASAT_PHY, ...ASAT_CHEM, ...ASAT_MATH];
      break;
  }
  const all = [...ASAT_IQ, ...subjectQs].slice(0, 30);
  const order = { easy: 0, medium: 1, hard: 2 };
  all.sort((a, b) => order[a.difficulty] - order[b.difficulty]);
  return all.map(q => ({ ...q, id: crypto.randomUUID() }));
};
